import{_ as s,o as e,c as t,a2 as p}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"古柏行","description":"","frontmatter":{"title":"古柏行","date":"2026-11-23T00:00:00.000Z","seq":17,"categories":["美文","唐诗三百首"],"collection":"《唐诗三百首 · 七言古诗》","tags":["唐诗三百首","唐"],"poem":true,"poem_quote":false,"author":"杜甫","source_book":"唐诗三百首"},"headers":[],"relativePath":"blogs/唐诗三百首·七言古诗/古柏行.md","filePath":"blogs/唐诗三百首·七言古诗/古柏行.md"}'),o={name:"blogs/唐诗三百首·七言古诗/古柏行.md"};function l(c,a,n,r,m,_){return e(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="古柏行" tabindex="-1">古柏行 <a class="header-anchor" href="#古柏行" aria-label="Permalink to &quot;古柏行&quot;">​</a></h1><p class="poem-meta">唐 · 杜甫　·　七言古诗</p><div class="poem"><p class="poem-stanza">孔明庙前有老柏，柯如青铜根如石。</p><p class="poem-stanza">霜皮溜雨四十围，黛色参天二千尺。</p><p class="poem-stanza">君臣已与时际会，树木犹为人爱惜。</p><p class="poem-stanza">云来气接巫峡长，月出寒通雪山白。</p><p class="poem-stanza">忆昨路绕锦亭东，先主武侯同閟宫。</p><p class="poem-stanza">崔嵬枝干郊原古，窈窕丹青户牖空。</p><p class="poem-stanza">落落盘踞虽得地，冥冥孤高多烈风。</p><p class="poem-stanza">扶持自是神明力，正直原因造化工。</p><p class="poem-stanza">大厦如倾要梁栋，万牛回首丘山重。</p><p class="poem-stanza">不露文章世已惊，未辞翦伐谁能送？</p><p class="poem-stanza">苦心岂免容蝼蚁，香叶终经宿鸾凤。</p><p class="poem-stanza">志士幽人莫怨嗟：古来材大难为用。</p></div>',3)])])}const z=s(o,[["render",l]]);export{d as __pageData,z as default};
